package com.documentverification.controller;
import com.documentverification.dao.*;import com.documentverification.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;
@WebServlet("/admin/document-types")
public class AdminServlet extends HttpServlet{private final DocumentTypeDAO types=new DocumentTypeDAO();private final AuditDAO audit=new AuditDAO();protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{long org=(Long)r.getSession().getAttribute("organizationId");try{r.setAttribute("items",types.findAll(org));r.setAttribute("csrfToken",CsrfUtil.token(r.getSession()));r.getRequestDispatcher("/WEB-INF/views/admin/document-types.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!CsrfUtil.valid(r)){s.sendError(403);return;}long org=(Long)r.getSession().getAttribute("organizationId"),uid=(Long)r.getSession().getAttribute("userId");try{String a=r.getParameter("action");long id=r.getParameter("id")==null?0:Long.parseLong(r.getParameter("id"));if("create".equals(a))types.create(org,ValidationUtil.required(r.getParameter("name"),"Name"),r.getParameter("description"));else if("update".equals(a))types.update(org,id,ValidationUtil.required(r.getParameter("name"),"Name"),r.getParameter("description"));else if("toggle".equals(a))types.setActive(org,id,"1".equals(r.getParameter("active")));audit.log(org,uid,"DOCUMENT_TYPE_CHANGED","Document type #"+id,r.getRemoteAddr());s.sendRedirect(r.getContextPath()+"/admin/document-types");}catch(Exception e){throw new ServletException(e);}}}
